{"file_path": "E:\TestProject\LinuxDo\linuxdo-codex.user.js", "new_string": "  function bindStealthKeys() {
    window.addEventListener("keydown", (e) => {
      // 设置面板开着时 Esc 先关面板（别再触发应急伪装）。
      // 这一条必须在这里办：本监听器注册在 bindSettingsKeys 之前，
      // 否则面板关掉之后这次 Esc 会被当成「第一下」，紧接着的第二下就误开伪装。
      if (e.key === "Escape" && settingsOpen()) {
        e.preventDefault();
        closeSettings();
        return;
      }
      // 灯箱开着时 Esc 属于灯箱
      if (e.key === "Escape" && activeLightbox) return;
      const spec = String(cfg("stealthKey") || "esc2").toLowerCase();
      if (spec === "esc2" && e.key === "Escape") {
        // 应急键的价值就在于「任何时候一按就藏」，所以在输入框里打字也照样生效；
        // 想在输入框里取消输入，单次 Esc 即可（单次本来也不触发）
        const now = Date.now();
        if (now - lastEscAt < 450) {
          lastEscAt = 0;
          e.preventDefault();
          setBoss(!bossOn());
        } else {
          lastEscAt = now;
        }
        return;
      }
      if (bossKeyMatch(e, spec) || bossKeyMatch(e, "ctrl+shift+h")) {
        e.preventDefault();
        e.stopPropagation();
        setBoss(!bossOn());
      }
    }, true);
  }
