content.text:
Now the CDP runner. Key considerations:
- Launch Chrome headless with the URL.
- Poll /json/list for the page target.
- Connect WebSocket, enable Runtime/Log/Page.
- Collect exceptionThrown + console errors.
- Run the in-page probe.

Write the probe as a JS string with careful escaping. I'll put the probe in a separate file `tools/smoke/probe.js` (a function body as a string) and read it from the runner, then `Runtime.evaluate({expression: "(async () => {" + probe + "})()"})`. That keeps things readable.

Probe content (page context):

```js
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
const out = [];
const ok = (name, pass, detail) => out.push({ name, pass: !!pass, detail: detail === undefined ? "" : String(detail) });
const q = (s) => document.querySelector(s);
const qa = (s) => [...document.querySelectorAll(s)];
const key = (k, opts) => window.dispatchEvent(new KeyboardEvent("keydown", Object.assign({ key: k, bubbles: true, cancelable: true }, opts || {})));
const dblEsc = async () => { key("Escape"); await sleep(60); key("Escape"); await sleep(120); };

// 1. 启动
ok("rail 已渲染且带归属标记", !!q('.codex-rail[data-cx-owner="linuxdo-codex-v1"]'));
ok("main 已渲染", !!q('.codex-main[data-cx-owner="linuxdo-codex-v1"]'));
ok("html 上有 codex-theme", document.documentElement.classList.contains("codex-theme"));
ok("锁定路由隐藏原生主内容", document.documentElement.classList.contains("codex-locked"));
await sleep(400); // 等列表 JSON
ok("列表行渲染", qa(".cx-trow").length >= 5, qa(".cx-trow").length + " 行");
ok("列表标题", (q(".cx-proj-head h1")||{}).textContent === "最新", (q(".cx-proj-head h1")||{}).textContent);
// 2. 伪装：标题 / 品牌名 / favicon
ok("标签页标题已伪装", document.title === "lib.rs — platform", document.title);
ok("品牌名 = Codex", (q("[data-brand-name]")||{}).textContent === "Codex", (q("[data-brand-name]")||{}).textContent);
ok("favicon 换成 Codex 图标", (document.getElementById("codex-favicon")||{}).getAttribute?.("href")?.startsWith("data:image/svg+xml"));
// 3. CSS 变量（缩略图）
const rootStyle = getComputedStyle(document.documentElement);
ok("--ldx-thumb-w 生效", rootStyle.getPropertyValue("--ldx-thumb-w").trim() === "260px", rootStyle.getPropertyValue("--ldx-thumb-w"));
ok("--ldx-thumb-h 生效", rootStyle.getPropertyValue("--ldx-thumb-h").trim() === "170px");
// 4. 应急伪装键
await dblEsc();
ok("连按两下 Esc 进入伪装视图", q(".ldx-boss") && !q(".ldx-boss").hidden && document.documentElement.classList.contains("ldx-boss-on"));
ok("伪装视图有构建日志", /cargo test/.test((q("[data-boss-log]")||{}).textContent || ""));
