const fs=require('fs'),zlib=require('zlib'),path=require('path');
const b='C:\\\\Users\\\\yerirong\\\\.dsh\\\\sessions\\\\--E-TestProject-LinuxDo--';
console.log('zstd api:', typeof zlib.zstdDecompressSync);
const files=[];
(function walk(d){ for(const e of fs.readdirSync(d,{withFileTypes:true})){ const p=path.join(d,e.name); e.isDirectory()?walk(p):files.push(p);} })(b);
const MARK='/ @version      0.3.1';
for(const f of files){
  let txt; try{ txt=zlib.zstdDecompressSync(fs.readFileSync(f)).toString('utf8'); }catch(err){ console.log(f.split('\\\\').pop(), 'decompress fail', err.message); continue; }
