content.arguments:
{"command": "Get-ChildItem tools\recover | Select-Object Length,Name
"--- 删除导出的会话记录（体积大且含会话内容），只保留工具脚本 ---"
Get-ChildItem tools\recover\*.jsonl | ForEach-Object { Remove-Item -LiteralPath $_.FullName -Force; "removed $($_.Name)" }
"--- 最终工作区 ---"
Get-ChildItem -Recurse -File | Sort-Object FullName | ForEach-Object { "{0,9}  {1}" -f $_.Length, $_.FullName.Replace((Get-Location).Path + '\','') }
"--- 交付物完整性 ---"
node --check linuxdo-codex.user.js; if($?){"syntax OK"}
node -e "const c=require('crypto'),f=require('fs');console.log('sha256', c.createHash('sha256').update(f.readFileSync('linuxdo-codex.user.js')).digest('hex').toUpperCase())"", "description": "Clean recovery dumps and verify final workspace"}

