{"command": "$b='C:\Users\yerirong\.dsh\sessions\--E-TestProject-LinuxDo--'
Get-ChildItem $b -Recurse -File -Filter 'session.v4.jsonl.zstd' | ForEach-Object {
  $short=$_.Directory.Name.Substring(0,20)
  node tools/recover/dump-session.js $_.FullName "tools\recover\$short.jsonl"
  "  -> $short"
}
"--- 找出包含 edit 工具调用的会话 ---"
Get-ChildItem tools\recover\*.jsonl | ForEach-Object {
  $t=Get-Content $_.FullName -Raw
  "{0,-32} editCalls={1,-6} copyItem={2}" -f $_.Name, ([regex]::Matches($t,'"name":"edit"')).Count, ([regex]::Matches($t,'Copy-Item')).Count
}", "description": "Re-dump transcripts and locate edit tool calls", "timeoutMs": 300000}

